from rest_framework import serializers
from django.utils import timezone
from .models import Card
from ..memberships.models import Memberships


class CardSerializer(serializers.ModelSerializer):

    class Meta:
        model = Card
        fields = "__all__"

        # These fields are generated by the server.
        read_only_fields = (
            "id",
            "created_at",
            "updated_at",
        )

    def validate_card_number(self, value):
        value = value.strip()

        if not value:
            raise serializers.ValidationError(
                "Card number is required."
            )

        # Exclude the current instance during updates.
        queryset = Card.objects.filter(card_number__iexact=value)

        if self.instance:
            queryset = queryset.exclude(pk=self.instance.pk)

        if queryset.exists():
            raise serializers.ValidationError(
                "This card number already exists."
            )

        return value

    def validate_expiration_date(self, value):
        if value is None:
            return value

        issued_at = (
            self.initial_data.get("issued_at")
            if self.initial_data
            else None
        )

        if self.instance and not issued_at:
            issued_at = self.instance.issued_at

        if issued_at:
            try:
                from django.utils.dateparse import parse_datetime

                if isinstance(issued_at, str):
                    issued_at = parse_datetime(issued_at)

                if issued_at and timezone.is_naive(issued_at):
                    issued_at = timezone.make_aware(issued_at)

                if issued_at and value <= issued_at:
                    raise serializers.ValidationError(
                        "Expiration date must be later than the issue date."
                    )
            except (TypeError, ValueError):
                raise serializers.ValidationError(
                    "Invalid issue date."
                )

        elif value <= timezone.now():
            raise serializers.ValidationError(
                "Expiration date must be in the future."
            )

        return value

    def validate(self, attrs):
        # For partial updates, use existing values where needed.
        membership = attrs.get(
            "membership",
            getattr(self.instance, "membership", None),
        )
        card_type = attrs.get(
            "card_type",
            getattr(self.instance, "card_type", None),
        )
        position = attrs.get(
            "position",
            getattr(self.instance, "position", None),
        )
        organization = attrs.get(
            "organization",
            getattr(self.instance, "organization", None),
        )

        # A card must be associated with a membership.
        if membership is None:
            raise serializers.ValidationError({
                "membership": "A membership is required."
            })

        # Only approved memberships can receive cards.
        if membership.status != Memberships.Status.APPROVED:
            raise serializers.ValidationError({
                "membership": (
                    "A card can only be issued to an approved member."
                )
            })

        if organization is None:
            raise serializers.ValidationError({
                "organization": "An organization is required."
            })

        # Membership cards must not represent leadership positions.
        if card_type == Card.CardType.MEMBERSHIP_CARD and position is not None:
            raise serializers.ValidationError({
                "position": (
                    "A membership card must not have a leadership position."
                )
            })

        # Leadership cards must specify a position.
        if card_type == Card.CardType.LEADERSHIP_CARD and position is None:
            raise serializers.ValidationError({
                "position": (
                    "A leadership card requires an approved position."
                )
            })

        # The position and card organization must match.
        if position is not None and position.organization_id != organization.pk:
            raise serializers.ValidationError({
                "organization": (
                    "The card organization must match the position's organization."
                )
            })

        # A card's organization must match the member's organization.
        if (
            membership.organization_id != organization.pk
            and card_type == Card.CardType.MEMBERSHIP_CARD
        ):
            raise serializers.ValidationError({
                "organization": (
                    "The membership card organization must match the membership."
                )
            })

        return attrs
